18: // Detection order per SCOPE.md: small.toml -> --entry -> framework hint -> filename
19: // convention -> only .py file -> fail with the one-line fix.
20: function detect(dir, flags = {}) {
21:   const tomlPath = path.join(dir, 'small.toml');
22:   const config = fs.existsSync(tomlPath) ? parse(fs.readFileSync(tomlPath, 'utf8')) : {};
23:   const name = config.name || path.basename(dir).toLowerCase().replace(/[^a-z0-9-]/g, '-');
24:   const pick = (entry, via) => {
25:     const full = path.join(dir, entry);
26:     if (!fs.existsSync(full)) throw new Error(`entry ${entry} (via ${via}) does not exist`);
27:     const source = fs.readFileSync(full, 'utf8');
28:     return { name, entry, framework: config.framework || frameworkOf(source), via, config };
29:   };
30:   if (config.entry) return pick(config.entry, 'small.toml');
31:   if (flags.entry) return pick(flags.entry, '--entry');
32:   const pys = fs.readdirSync(dir).filter((f) => f.endsWith('.py'));
33:   for (const f of pys) {
34:     if (frameworkOf(fs.readFileSync(path.join(dir, f), 'utf8')) !== 'script') return pick(f, 'framework hint');
35:   }
36:   for (const f of ['app.py', 'main.py', 'server.py']) {
37:     if (pys.includes(f)) return pick(f, 'filename convention');
38:   }
39:   if (pys.length === 1) return pick(pys[0], 'only .py file');
40:   throw new Error('cannot find the app entry — add entry = "app.py" to small.toml');
41: }
